async def act(page):
    import asyncio

    # Navigate to the Orders management grid (deterministic starting state)
    await page.goto('/index.php/admin/sales_order/')
    await page.wait_for_load_state('networkidle')
    await asyncio.sleep(0.5)

    # 1) Locate the Status filter combobox by accessible name
    status_combobox = page.get_by_role('combobox', name='Status')
    if await status_combobox.count() == 0:
        # Fallback: scan comboboxes and inspect attributes for a 'status' hint
        comboboxes = page.get_by_role('combobox')
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            try:
                aria = (await cb.get_attribute('aria-label')) or ''
            except Exception:
                aria = ''
            try:
                name_attr = (await cb.get_attribute('name')) or ''
            except Exception:
                name_attr = ''
            try:
                roledesc = (await cb.get_attribute('aria-roledescription')) or ''
            except Exception:
                roledesc = ''
            if 'status' in aria.lower() or 'status' in name_attr.lower() or 'status' in roledesc.lower():
                status_combobox = cb
                break

    if await status_combobox.count() == 0:
        # Could not find Status filter on the Orders page
        print('NO_STATUS_FILTER_FOUND')
        return

    # 2) Try to select the 'On Hold' option (native <select> semantics preferred)
    selected = False
    try:
        await status_combobox.select_option(label='On Hold')
        selected = True
    except Exception:
        # Fallback: inspect option visible labels and values and choose the first that contains 'hold'
        try:
            opt_locator = status_combobox.get_by_role('option')
            if await opt_locator.count() > 0:
                opt_texts = await opt_locator.all_inner_texts()
                pick_label = None
                for t in opt_texts:
                    if 'hold' in t.lower():
                        pick_label = t
                        break
                if pick_label:
                    await status_combobox.select_option(label=pick_label)
                    selected = True
                else:
                    opt_values = await opt_locator.evaluate_all('els => els.map(e => e.value)')
                    for v in opt_values:
                        if v and 'hold' in v.lower():
                            await status_combobox.select_option(value=v)
                            selected = True
                            break
        except Exception:
            # Non-native control or options inaccessible; continue to submit filter via Enter or Search button
            pass

    # 3) Apply the filter by clicking the Search button (accessible-name preferred), else press Enter
    search_btn = page.get_by_role('button', name='Search')
    if await search_btn.count() == 0:
        # Scan visible buttons for one whose text contains 'Search'
        btns = page.get_by_role('button')
        btn_count = await btns.count()
        found_btn = None
        for i in range(btn_count):
            b = btns.nth(i)
            try:
                txt = (await b.inner_text()).strip()
            except Exception:
                txt = ''
            if 'search' in txt.lower():
                found_btn = b
                break
        if found_btn is not None:
            search_btn = found_btn
        else:
            # As a last resort, press Enter on the combobox to submit/apply the filter
            await status_combobox.first.press('Enter')

    if await search_btn.count() > 0:
        await search_btn.first.click()

    # 4) Wait for the grid to refresh
    await page.wait_for_load_state('networkidle')
    await asyncio.sleep(0.5)

    # 5) Collect order identifiers from the orders grid using accessibility-role centric selectors
    rows = page.get_by_role('row')
    orders = []
    row_count = await rows.count()
    for i in range(row_count):
        row = rows.nth(i)
        links = row.get_by_role('link')
        if await links.count() > 0:
            link_count = await links.count()
            for j in range(link_count):
                l = links.nth(j)
                try:
                    txt = (await l.inner_text()).strip()
                except Exception:
                    txt = ''
                if not txt:
                    continue
                # Heuristic: order increment ids usually contain digits and are at least 4 chars
                if any(c.isdigit() for c in txt) and len(txt) >= 4:
                    low = txt.lower()
                    if not low.startswith(('customer', 'actions', 'item', 'product')):
                        orders.append(txt)
                        break

    if not orders:
        print('NO_ON_HOLD_ORDERS_FOUND')
    else:
        print('\n'.join(orders))

